  const reforging=window.StepQuestReforging.create({getGame:()=>g,state,el,button,fmt,titled,itemIcon,rarity,tier,bindItem,dialog,run,inspect,render,isBusy:()=>busy,isLocked:()=>busy||active()||travelling()||arenaFighting(),api});
  const {junkSaleDialog}=window.StepQuestInventorySales.create({getGame:()=>g,isBusy:()=>busy,api,root,signal:events.signal,state,el,button,fmt,rarity,tier,dialog,run,active});
  const {definition,setDetails,comparisonDetails,details,enchantmentDetails,refinementDetails}=window.StepQuestItemDetails.create({getGame:()=>g,el,fmt,tier,rollText,rarity,itemIcon,requestComparison:item=>comparisons.request(item,true)});
  function rarity(node,id){const r=tier(id);node.classList.add('rarity-text');node.dataset.rarity=id;node.style.setProperty('--item-color-dark',r.dark);node.style.setProperty('--item-color-light',r.light);return node;}
  function icon(kind){const n=document.createElementNS('http://www.w3.org/2000/svg','svg');n.setAttribute('viewBox','0 0 64 64');n.setAttribute('class','game-icon icon-'+kind);n.setAttribute('aria-hidden','true');const p=document.createElementNS(n.namespaceURI,'path');p.setAttribute('d',PATHS[kind]||PATHS.ring);n.append(p);return n;}
  function pixelIcon(kind){const n=document.createElementNS('http://www.w3.org/2000/svg','svg');n.setAttribute('viewBox','0 0 32 32');n.setAttribute('class','pixel-action-icon');n.setAttribute('aria-hidden','true');n.setAttribute('shape-rendering','crispEdges');for(const [fill,path]of window.StepQuestActionIcons[kind]||window.StepQuestActionIcons.book){const p=document.createElementNS(n.namespaceURI,'path');p.setAttribute('fill',fill);p.setAttribute('d',path);n.append(p);}return n;}
  function actionHint(target,label){target.setAttribute('aria-label',label);target.dataset.actionHint=label;const show=()=>{hideTooltip();if(!target.isConnected)return;actionTooltip=el('aside','action-tooltip',label);actionTooltip.id='action-tooltip';actionTooltip.setAttribute('role','tooltip');root.firstElementChild.append(actionTooltip);target.setAttribute('aria-describedby',actionTooltip.id);const a=target.getBoundingClientRect(),b=actionTooltip.getBoundingClientRect();const left=Math.max(16,Math.min(a.left+a.width/2-b.width/2,innerWidth-b.width-16));let top=a.top-b.height-10;const note=root.querySelector('.action-status')?.getBoundingClientRect();if(target.closest('.game-bottom')&&note?.height&&left<note.right&&left+b.width>note.left&&top<note.bottom&&top+b.height>note.top)top=note.top-b.height-8;actionTooltip.style.left=left+'px';actionTooltip.style.top=Math.max(16,top)+'px';};target.addEventListener('mouseenter',show);target.addEventListener('focusin',show);target.addEventListener('mouseleave',hideTooltip);target.addEventListener('focusout',hideTooltip);target.addEventListener('click',hideTooltip);}
  function iconAction(label,kind,fn,cls=''){const b=button('',fn,'icon-action '+cls);b.append(pixelIcon(kind));b.disabled=busy;actionHint(b,label);return b;}
  function itemIcon(item){const n=el('img','item-sprite');n.src=`assets/items/${item.sprite}.png`;n.alt='';n.width=32;n.height=32;n.draggable=false;return n;}
  function action(label,kind,fn,cls=''){const b=button('',fn,'game-action '+cls);b.append(icon(kind),el('span','',label));b.disabled=busy;return b;}
  function titled(title,subtitle){const n=el('div','game-panel-heading');n.append(el('h2','',title));if(subtitle)n.append(el('p','',subtitle));return n;}
  function focusKey(node){if(!node)return null;if(node.id)return {id:node.id};for(const key of ['itemId','location','category','battleAction','actionHint','atlasNode','chronicle'])if(node.dataset?.[key])return {key,value:node.dataset[key]};return null;}
  function restoreFocus(key){if(!key||document.querySelector('dialog[open]'))return;const target=key.id?document.getElementById(key.id):[...root.querySelectorAll('[data-'+key.key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+']')].find(n=>n.dataset[key.key]===key.value);if(target&&!target.disabled)target.focus({preventScroll:true});}
  function closeDialog(){const d=document.getElementById('game-dialog');if(d){d.close();d.remove();}}
  function dialog(title,description,content,buttons=[],back=null){const opener=focusKey(document.activeElement);hideTooltip();closeDialog();const d=el('dialog','game-dialog');d.id='game-dialog';const heading=el('h2','',title);heading.tabIndex=-1;const body=el('div','game-dialog-body');if(description)body.append(el('p','',description));if(content)body.append(content);const actions=el('div','actions');actions.append(button(back?'Torna allo zaino':'Chiudi',back||closeDialog,'secondary'));buttons.forEach(b=>actions.append(b));d.append(el('div','eyebrow','CRONACHE DEI SENTIERI'),heading,body,actions);d.onclose=()=>{d.remove();restoreFocus(opener);if(!busy)comparisons.visible();};if(back)d.oncancel=e=>{e.preventDefault();back();};document.body.append(d);d.showModal();heading.focus({preventScroll:true});body.scrollTop=0;comparisons.visible();}

  async function run(operation,message,after){if(busy)return false;stateEpoch++;const focus=focusKey(document.activeElement);busy=true;hideTooltip();closeDialog();root.setAttribute('aria-busy','true');root.querySelectorAll('button').forEach(b=>b.disabled=true);const note=root.querySelector('.action-status');if(note)note.textContent='Operazione in corso…';let failure;const knownMemories=new Set(g.chronicles.badges.filter(b=>b.earned).map(b=>b.id));let newMemory;const wasFighting=active(),previousBattleId=g.battle?.id,previousExpedition=g.expedition?.status;try{const result=await operation();if(!result.ok)throw new Error(result.error.message);g=result.value;newMemory=g.chronicles.badges.find(b=>b.earned&&!knownMemories.has(b.id));state.message=(typeof message==='function'?message(g):message)||'Salvataggio aggiornato.';if((wasFighting||g.battle?.id!==previousBattleId)&&g.battle?.status==='won')state.message=`Vittoria! +${g.battle.rewards.xp} XP, +${g.battle.rewards.coins+(g.battle.rewards.autoSaleCoins||0)} monete.`;if((wasFighting||g.battle?.id!==previousBattleId)&&['lost','fled'].includes(g.battle?.status)){state.location='home';state.message=g.battle.status==='lost'?'Sei tornato al rifugio. Riposa prima di ripartire.':'Ritirata completata. Il tuo equipaggiamento è salvo.';}if(previousExpedition==='active'&&g.expedition?.status!=='active'){const e=g.expedition;state.message=e.status==='completed'?(e.rewards.researchPending?'Ricerca completata. Scegli uno dei due premi.':e.rewards.autoSold?.length?`Spedizione completata! +${fmt(e.rewards.coins+e.rewards.autoSaleCoins)} monete. Premio venduto dal filtro bottino.`:`Spedizione completata! +${fmt(e.rewards.coins)} monete e un oggetto premio.`):e.status==='lost'?'Spedizione interrotta. Metà della sacca è salva. Recupera al rifugio.':`Rientro sicuro: +${fmt(e.rewards.coins)} monete. Usa cibo o riposo per recuperare vita.`;if(e.status==='lost'||e.status==='returned')state.location='home';}}catch(error){failure=error.message;state.message=failure;}finally{busy=false;root.removeAttribute('aria-busy');render();restoreFocus(focus);}if(failure)dialog('Azione non disponibile',failure);else{if(after)after();if(previousExpedition==='active'&&g.expedition?.status==='completed'&&g.expedition.rewards?.finale)showWatchFinale(g.expedition.rewards.finale);if(newMemory&&typeof toast==='function')toast(window.StepQuestI18n.translate('La Gilda ricorderà questa impresa.')+' '+window.StepQuestI18n.translate(newMemory.name));}return !failure;}
  function showWatchFinale(memory=g.atlas.finale?.memory){if(memory)window.StepQuestWatch.ceremony({memory,el,button,dialog,onHome:()=>{closeDialog();state.location='home';render();}});}
  function importDailySteps(){
   run(()=>api.syncSteps(),result=>{
    const r=result.stepsImport,source=r.offline?'Garmin offline · dati di oggi già salvati':'Garmin oggi';
    if(r.dailyTotal===null)return `${source}: nessun dato disponibile. Nessun passo aggiunto.`;
    const guildNotice=r.guildSync?(r.guildSync.history==='partial'?'Storico passi della Gilda non aggiornato.':r.guildSync.activities==='online'?'Progressi della Gilda aggiornati.':'Attività non disponibili: puoi usare i passi'):'';
    const message=`${source}: ${fmt(r.dailyTotal)} passi · ${r.credited?'+'+fmt(r.credited)+' aggiunti a '+window.StepQuestI18n.verbatim(result.hero.name):'nessun nuovo passo da aggiungere'}. ${r.dailySync==='online'?'Bonus Garmin aggiornati.':r.dailySync==='partial'?'Sonno non disponibile; altri bonus aggiornati.':'Bonus Garmin non aggiornati; consulta il taccuino.'}`;
    return state.location==='guild'&&guildNotice?guildNotice:message;
   });
  }
  function exchangeDialog(resume=null){
   const block=g.rules.exchange_steps,max=Math.floor(g.hero.steps/block)*block;if(max<block)return;
   let amount=Math.min(max,1000);amount=Math.max(block,Math.floor(amount/block)*block);
   const content=el('div','conversion-panel'),label=el('label','','Passi da convertire');label.htmlFor='conversion-slider';
   const slider=el('input','conversion-slider');slider.id='conversion-slider';slider.type='range';slider.min=String(block);slider.max=String(max);slider.step=String(block);slider.value=String(amount);
   const output=el('output','conversion-preview');output.id='conversion-preview';output.htmlFor=slider.id;const remaining=el('p','conversion-remaining'),limits=el('div','conversion-limits');
   const confirm=button('',()=>{const selected=Number(slider.value),coins=selected/block*g.rules.exchange_coins;run(()=>api.exchangeSteps(selected),`Convertiti ${fmt(selected)} passi in ${fmt(coins)} monete.`,resume);},'','confirm-exchange');
   function update(){const selected=Number(slider.value),coins=selected/block*g.rules.exchange_coins;output.textContent=`${fmt(selected)} passi → ${fmt(coins)} monete`;remaining.textContent=`Dopo il cambio: ${fmt(g.hero.steps-selected)} passi e ${fmt(g.hero.coins+coins)} monete.`;confirm.textContent=`Converti · ${fmt(coins)} monete`;slider.setAttribute('aria-valuetext',`${fmt(selected)} passi per ${fmt(coins)} monete`);}
   const minButton=button('Minimo',()=>{slider.value=String(block);update();},'secondary'),maxButton=button('Massimo',()=>{slider.value=String(max);update();},'secondary');minButton.id='conversion-min';maxButton.id='conversion-max';limits.append(minButton,maxButton);
   slider.oninput=update;content.append(label,slider,limits,output,remaining);update();dialog('Converti passi in monete',`Disponibili: ${fmt(g.hero.steps)} passi · ${fmt(block)} passi = ${fmt(g.rules.exchange_coins)} monete`,content,[confirm]);
  }
  function monsterSprite(enemy,cls=''){const image=el('img','monster-sprite '+cls);image.src=`assets/monsters/${enemy.id||'wolf'}.png`;image.width=96;image.height=96;image.alt=enemy.name||'Mostro';image.draggable=false;return image;}
  function monsterGallery(){const gallery=el('div','monster-gallery');for(const enemy of g.enemies){const cell=el('div');cell.append(monsterSprite(enemy,'monster-preview'),el('span','',enemy.name));gallery.append(cell);}return gallery;}
  const autoMessage=result=>result.battle?.status==='active'?'Risolti 250 turni. Puoi continuare con Auto o scegliere un’azione.':'Combattimento risolto.';
  function hideTooltip(){clearTimeout(hideTimer);if(actionTooltip){document.querySelector(`[aria-describedby="action-tooltip"]`)?.removeAttribute('aria-describedby');actionTooltip.remove();actionTooltip=null;}if(tooltip)tooltip.hidden=true;tooltipTarget?.removeAttribute('aria-describedby');tooltipTarget=null;}
  function showTooltip(target,item){comparisons.prepare(item);clearTimeout(hideTimer);if(busy||!target.isConnected||document.querySelector('dialog[open]'))return;if(!tooltip){tooltip=el('aside','item-tooltip');tooltip.id='item-tooltip';tooltip.setAttribute('role','tooltip');tooltip.onmouseenter=()=>clearTimeout(hideTimer);tooltip.onmouseleave=hideTooltip;root.firstElementChild.append(tooltip);}tooltipTarget?.removeAttribute('aria-describedby');tooltipTarget=target;target.setAttribute('aria-describedby',tooltip.id);tooltip.replaceChildren(details(item));tooltip.dataset.itemId=item.id;tooltip.hidden=false;const a=target.getBoundingClientRect(),b=tooltip.getBoundingClientRect();let left=a.right+10;if(left+b.width>innerWidth-16)left=a.left-b.width-10;tooltip.style.left=Math.max(16,Math.min(left,innerWidth-b.width-16))+'px';tooltip.style.top=Math.max(16,Math.min(a.top,innerHeight-b.height-16))+'px';}
  function comparisonMark(c){return c.assessment?.recommendation==='better'?'↑':c.assessment?.recommendation==='worse'?'↓':c.assessment?'≈':'…';}
  function updateComparisonBadge(target,item){
   target.querySelectorAll('.upgrade-badge,.comparison-pending').forEach(n=>n.remove());
   const c=item.comparison,assessment=c?.assessment,available=c?.eligible&&!item.equippedSlot;
   target.dataset.comparisonState=assessment?.recommendation||(available?'pending':'none');
   const advice=assessment?.recommendation==='better'?'Equipaggiamento consigliato':assessment?.recommendation==='worse'?'Mantieni quello attuale':assessment?.recommendation==='same'?(assessment.uncertain||assessment.reason==='unresolved'?'Confronto non conclusivo':'Differenza minima'):'';
   target.setAttribute('aria-label',item.name+' · '+tier(item.rarity).name+(advice?' · '+window.StepQuestI18n.translate(advice):''));
   if(available&&(target.matches('.inventory-cell,.shop-row,.research-reward'))){
    if(assessment?.arrows){const badge=el('span','upgrade-badge','↑'.repeat(assessment.arrows));badge.setAttribute('aria-hidden','true');(target.querySelector('.shop-offer-value')||target).append(badge);}
    else if(!assessment){const pending=el('span','comparison-pending');pending.setAttribute('aria-hidden','true');(target.querySelector('.shop-offer-value')||target).append(pending);}
   }
  }
  function updateComparisons(ids){
   for(const id of ids){
    const item=comparisons.find(id);if(!item)continue;
    for(const target of document.querySelectorAll('[data-item-id]'))if(target.dataset.itemId===id&&target.matches('.inventory-cell,.shop-row,.equipment-slot,.research-reward'))updateComparisonBadge(target,item);
    const content=document.querySelector('#game-dialog .item-characteristics[data-item-id="'+id+'"]'),selectedSlot=content?.dataset.userComparisonSlot||item.comparison?.slot;
    for(const section of document.querySelectorAll('.gear-comparison[data-comparison-item]'))if(section.dataset.comparisonItem===id){const slot=section.closest('#game-dialog')?selectedSlot:item.comparison?.slot,c=item.comparisons.find(c=>c.slot===slot);if(c)section.replaceWith(comparisonDetails({...item,comparison:c}));}
    if(content){
     for(const button of content.querySelectorAll('[data-compare-slot]')){const c=item.comparisons.find(c=>c.slot===button.dataset.compareSlot);if(c){button.textContent=`${g.slotLabels[c.slot]} · ${comparisonMark(c)}`;button.setAttribute('aria-pressed',String(c.slot===selectedSlot));}}
     const dialog=content.closest('#game-dialog');
     for(const [attribute,prefix]of [['equipSlot','equip-item'],['buyEquipSlot','buy-equip']]){
      const buttons=[...dialog.querySelectorAll('button')].filter(b=>b.dataset[attribute]);
      buttons.forEach(b=>b.id=prefix+'-'+b.dataset[attribute]);const selected=buttons.find(b=>b.dataset[attribute]===selectedSlot);if(selected)selected.id=prefix==='buy-equip'?'buy-equip-item':prefix;
     }
    }
   }
   if(tooltip&&!tooltip.hidden){const bounds=tooltip.getBoundingClientRect();tooltip.style.top=Math.max(16,Math.min(bounds.top,innerHeight-bounds.height-16))+'px';}
  }
  function bindItem(target,item){comparisons.prepare(item);target.dataset.itemId=item.id;target.classList.toggle('enchanted-item',!!item.enchantment);updateComparisonBadge(target,item);target.dataset.rarity=item.rarity;target.style.setProperty('--item-color-dark',tier(item.rarity).dark);target.onmouseenter=()=>showTooltip(target,item);target.onmouseleave=()=>{hideTimer=setTimeout(hideTooltip,180);};target.addEventListener('focusin',()=>showTooltip(target,item));target.addEventListener('focusout',hideTooltip);target.addEventListener('click',hideTooltip);}
  function inspect(item,shop=false,returnTo=null){
   comparisons.prepare(item);comparisons.request(item,true);
   const buttons=[];
   if(shop){
    const buy=button(`Compra · ${fmt(item.price)}`,()=>run(()=>api.buyItem(item.id),`${item.name} acquistato.`),'','buy-item');buy.disabled=busy||g.hero.coins<item.price||active();buttons.push(buy);
    for(const c of item.comparisons||[]){const b=button(item.slot==='ring'?`Compra e indossa · ${g.slotLabels[c.slot]}`:'Compra e indossa',()=>run(()=>api.buyAndEquip(item.id,c.slot),`${item.name} acquistato e indossato.`),'',c.slot===item.comparison.slot?'buy-equip-item':'buy-equip-'+c.slot);b.dataset.buyEquipSlot=c.slot;b.disabled=busy||active()||!c.eligible||g.hero.coins<item.price;buttons.push(b);}
    if(g.hero.coins<item.price&&g.hero.steps>=g.rules.exchange_steps&&!active()){const change=button('Converti passi',()=>exchangeDialog(()=>{const offer=g.merchant.offers.find(i=>i.id===item.id);if(offer)inspect(offer,true);}),'secondary','exchange-for-item');buttons.push(change);}
   }else{
    const equipped=!!item.equippedSlot;
    if(item.effect){const b=button('Usa oggetto',()=>active()?combat('potion',item.id,returnTo):run(()=>api.useItem(item.id),'Oggetto utilizzato.',returnTo),'','use-item');b.disabled=busy||item.effect.kind==='food'&&active()||['heal','food'].includes(item.effect.kind)&&g.hero.hp>=g.hero.stats.health||item.effect.kind==='guard'&&!active()||item.effect.kind==='antidote'&&!(g.battle?.buffs?.poison>0);buttons.push(b);}
    else if(!equipped){for(const c of item.comparisons||[]){const b=button(item.slot==='ring'?`Indossa · ${g.slotLabels[c.slot]}`:'Equipaggia',()=>run(()=>api.equipItem(item.id,c.slot),`${item.name} equipaggiato.`,returnTo),'',c.slot===item.comparison.slot?'equip-item':'equip-item-'+c.slot);b.dataset.equipSlot=c.slot;b.disabled=busy||active()||!c.eligible;buttons.push(b);}}
    else if(item.slot!=='weapon'){const b=button('Togli',()=>run(()=>api.unequipItem(item.equippedSlot),'Oggetto riposto nello zaino.',returnTo),'secondary','unequip-item');b.disabled=busy||active();buttons.push(b);}
    const sell=button(`Vendi · ${fmt(item.sellPrice)}`,()=>dialog('Vendi oggetto',`${item.name}: riceverai ${fmt(item.sellPrice)} monete.`,null,[button('Conferma vendita',()=>run(()=>api.sellItem(item.id),'Oggetto venduto.',returnTo),'','confirm-sale')]),'secondary','sell-item');sell.disabled=busy||equipped||active();buttons.push(sell);
   }
   const content=details(item);if(item.slot==='ring'&&!item.equippedSlot){const choices=el('div','ring-comparison-choices');choices.setAttribute('role','group');choices.setAttribute('aria-label','Slot da confrontare');for(const c of item.comparisons){const b=button(`${g.slotLabels[c.slot]} · ${comparisonMark(c)}`,()=>{hideTooltip();content.dataset.userComparisonSlot=c.slot;const previous=content.querySelector('.gear-comparison');previous.replaceWith(comparisonDetails({...item,comparison:c}));choices.querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));},'secondary');b.dataset.compareSlot=c.slot;b.setAttribute('aria-pressed',String(c.slot===item.comparison.slot));choices.append(b);}content.insertBefore(choices,content.querySelector('.gear-comparison'));}
   dialog(item.name,shop?(g.hero.coins<item.price?'Monete insufficienti.':`Portafoglio: ${fmt(g.hero.coins)} monete`):'Caratteristiche dell’oggetto',content,buttons,returnTo);rarity(document.querySelector('#game-dialog h2'),item.rarity);
  }
  function junkSaleButton(returnTo=null){const label=active()?'Vendita in blocco · disponibile dopo lo scontro':'Vendita in blocco',b=returnTo?button('Vendita in blocco',()=>junkSaleDialog(returnTo),'secondary inventory-sale'):iconAction(label,'coins',()=>junkSaleDialog(returnTo),'inventory-sale');b.id='sell-inferior';b.title=label;b.disabled=busy||active();return b;}
  function beginBattle(){if(busy||active())return;if(travelling()){state.wildMode='expedition';state.location='wilds';render();return;}if(g.hero.hp<Math.max(15,g.hero.stats.health*.2)){state.message='Vita insufficiente: usa Riposa qui, poi riparti.';render();return;}return state.automatic?run(()=>api.startAutoBattle(state.difficulty,crypto.randomUUID()),autoMessage):run(()=>api.startBattle(state.difficulty),'Scontro iniziato.');}
